describe('Login Form Accessibility', () => {
    beforeEach(() => {
        cy.visit('/login');
    });

    it('should allow user to navigate through the login form using keyboard', () => {
        cy.get('input[name="username"]').focus().tab();
        cy.focused().should('have.attr', 'name', 'password');
        cy.focused().tab();
        cy.focused().should('have.attr', 'type', 'submit');
    });

    it('should submit the form when Enter key is pressed', () => {
        cy.get('input[name="username"]').type('testuser').tab();
        cy.get('input[name="password"]').type('password123').tab();
        cy.get('input[type="submit"]').type('{enter}');
        cy.url().should('include', '/dashboard');
    });
});
